const record=$input.first().json.strategy_text;
const sourceCommit=$('02 · Pin Alpha main').first().json.sha;
const candidatePath=$('01 · Select candidate').first().json.candidate_path;
const base={origin:'manual',source_commit:sourceCommit,candidate_path:candidatePath,source_ref:'HCH725/alpha-strategy-research@'+sourceCommit+'/'+candidatePath,qlib_run_id:null,run_state:'NOT_SUBMITTED'};
if(typeof record!=='string'||!record.startsWith('---\n')) return [{json:{...base,route:'NEEDS_REVIEW',reason:'GitHub record has no readable YAML frontmatter'}}];
const end=record.indexOf('\n---',4);
if(end<0) return [{json:{...base,route:'NEEDS_REVIEW',reason:'Unterminated YAML frontmatter'}}];
const fm=record.slice(4,end);
const field=k=>{const m=fm.match(new RegExp('^'+k+':\\s*(.*?)\\s*$','m'));return m?m[1].trim().replace(/^["']|["']$/g,''):null;};
const schema=field('schema'),hb=field('hb_ready_status'),implementation=field('implementation_status'),adoption=field('adoption');
let reason='';
if(schema!=='strategy-research-record-v1'||hb!=='PASS') reason='Invalid schema or HB_READY not PASS';
else if(implementation!=='implemented') reason='HB_READY admission is not executable implementation';
else reason='No verified Qlib executable config, data snapshot, parity or native run ID attached';
return [{json:{...base,schema,hb_ready_status:hb,implementation_status:implementation,adoption,route:reason==='Invalid schema or HB_READY not PASS'?'NEEDS_REVIEW':'HOLD',reason,market_data_ready:null,execution_path_supported:null}}];
